(()=>{
 const root=document.body.classList.contains('style-guide')?'../':'';
 document.querySelectorAll('.country-picker').forEach((picker)=>{
  const data=JSON.parse(picker.dataset.countries),native=picker.querySelector('select'),trigger=picker.querySelector('.country-trigger'),panel=picker.querySelector('.country-panel'),search=picker.querySelector('.country-search'),list=picker.querySelector('.country-options'),empty=picker.querySelector('.country-empty');
  let selected='au';
  const close=(focus=false)=>{panel.hidden=true;trigger.setAttribute('aria-expanded','false');if(focus)trigger.focus();};
  function render(){const q=search.value.trim().toLowerCase();const matches=data.filter(c=>(c.name+' '+c.code+' '+c.dial).toLowerCase().includes(q));list.replaceChildren();empty.hidden=matches.length>0;matches.forEach(c=>{const b=document.createElement('button');b.type='button';b.className='country-option';b.role='option';b.setAttribute('aria-selected',String(c.code===selected));b.innerHTML=`<img src="${root}assets/flags/${c.code}.svg" alt="" width="24" height="18"><span class="country-name"></span><span class="country-dial"></span>`;b.querySelector('.country-name').textContent=c.name;b.querySelector('.country-dial').textContent=c.dial;b.addEventListener('click',()=>{selected=c.code;native.selectedIndex=data.findIndex(x=>x.code===selected);native.dispatchEvent(new Event('change',{bubbles:true}));trigger.querySelector('img').src=`${root}assets/flags/${selected}.svg`;trigger.querySelector('span').textContent=c.dial;trigger.setAttribute('aria-label',`Country calling code, ${c.name} ${c.dial}`);close(true);});list.append(b);});}
  trigger.addEventListener('click',()=>{if(!panel.hidden)return close();panel.hidden=false;trigger.setAttribute('aria-expanded','true');search.value='';render();search.focus();});search.addEventListener('input',render);
  picker.addEventListener('keydown',e=>{if(panel.hidden)return;if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close(true);}const opts=[...list.querySelectorAll('button')],i=opts.indexOf(document.activeElement);if(e.key==='ArrowDown'){e.preventDefault();opts[Math.min(i+1,opts.length-1)]?.focus();}if(e.key==='ArrowUp'){e.preventDefault();if(i<=0)search.focus();else opts[i-1]?.focus();}if(e.key==='Home'&&i>=0){e.preventDefault();opts[0]?.focus();}if(e.key==='End'&&i>=0){e.preventDefault();opts.at(-1)?.focus();}});
  document.addEventListener('click',e=>{if(!picker.contains(e.target))close();});picker.addEventListener('focusout',()=>setTimeout(()=>{if(!picker.contains(document.activeElement))close();},0));
 });
 if(window.Swiper)document.querySelectorAll('.story-gallery').forEach(el=>new Swiper(el,{speed:matchMedia('(prefers-reduced-motion: reduce)').matches?0:420,grabCursor:true,simulateTouch:true,allowTouchMove:true,touchStartPreventDefault:false,preventClicks:true,preventClicksPropagation:true,threshold:5,longSwipesRatio:.25,keyboard:{enabled:true,onlyInViewport:true},a11y:{enabled:true},pagination:{el:el.querySelector('.story-pagination'),clickable:true},navigation:{prevEl:el.querySelector('.story-prev'),nextEl:el.querySelector('.story-next')}}));
 document.querySelectorAll('.gate-toggle').forEach(b=>b.addEventListener('click',()=>{const art=b.closest('.solar-field-art'),open=art.classList.toggle('is-open');b.setAttribute('aria-pressed',String(open));b.setAttribute('aria-label',open?'Close barrier':'Open barrier');b.querySelector('span').textContent=open?'Close barrier':'Open barrier';}));
})();
